comp=str.maketrans("ACGT","TGCA")
def rc(s): return s.translate(comp)[::-1]
stops={"TAA","TAG","TGA"}

def scan(s):
    res=[]
    for frame in range(3):
        i=frame; start=None
        while i+3<=len(s):
            cod=s[i:i+3]
            if cod=="ATG" and start is None: start=i
            if cod in stops:
                if start is not None:
                    res.append((start,i+3,(i+3-start)//3)); start=None
            i+=3
        # open ORF to end
        if start is not None:
            res.append((start,len(s)-(len(s)-start)%3,(len(s)-start)//3))
    return res

